PREFIX :     <https://example.org/bivak#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?label
WHERE {
  ?class rdfs:subClassOf :Shelter ;
         rdfs:label ?label .
  FILTER (lang(?label) = "cs")
}
ORDER BY ?label

PREFIX :     <https://example.org/bivak#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?label
WHERE {
  ?spot a :Spot ;
        rdfs:label ?label .
  FILTER (lang(?label) = "cs")
  FILTER NOT EXISTS { ?spot :liesWithin ?area }
}

PREFIX :     <https://example.org/bivak#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?label (COUNT(?act) AS ?activities)
WHERE {
  ?stay :includesActivity ?act ;
        rdfs:label ?label .
  FILTER (lang(?label) = "cs")
}
GROUP BY ?label
ORDER BY DESC(?activities) ?label

PREFIX :     <https://example.org/bivak#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?label (COUNT(DISTINCT ?area) AS ?areas)
WHERE {
  ?spot a :Spot ;
        rdfs:label ?label .
  FILTER (lang(?label) = "cs")
  OPTIONAL { ?spot :liesWithin+ ?area }
}
GROUP BY ?label
ORDER BY DESC(?areas) ?label

PREFIX :     <https://example.org/bivak#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

CONSTRUCT { ?spot :inForest ?forest }
WHERE {
  ?spot a :Spot ;
        :liesWithin+ ?forest .
  ?forest a :Forest .
}

