@prefix act:  <https://example.org/act/> .
@prefix bv:   <https://example.org/bivak#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .

# --- (a) SKOS ---
act:schema a skos:ConceptScheme ;
    skos:prefLabel "Typy činností"@cs , "Activity types"@en ;
    skos:hasTopConcept act:Camp .

act:Camp a skos:Concept ;
    skos:inScheme act:schema ;
    skos:topConceptOf act:schema ;
    skos:prefLabel "Táborová činnost"@cs , "Camp activity"@en ;
    skos:notation "CAMP" ;
    skos:narrower act:Cooking , act:Fire .

act:Cooking a skos:Concept ;
    skos:inScheme act:schema ;
    skos:broader act:Camp ;
    skos:prefLabel "Vaření"@cs , "Cooking"@en ;
    skos:altLabel "Příprava jídla"@cs ;
    skos:notation "COOK" ;
    skos:definition "Příprava teplého jídla na místě pobytu."@cs .

act:Fire a skos:Concept ;
    skos:inScheme act:schema ;
    skos:broader act:Camp ;
    skos:prefLabel "Oheň"@cs , "Fire"@en ;
    skos:notation "FIRE" ;
    skos:definition "Rozdělávání a udržování ohně."@cs .

# --- (b) RDFS ---
bv:Hut a rdfs:Class ;
    rdfs:subClassOf bv:Shelter ;
    rdfs:label "Chata"@cs , "Hut"@en .

bv:capacity a rdf:Property ;
    rdfs:label "kapacita"@cs , "capacity"@en ;
    rdfs:domain bv:Hut ;
    rdfs:range xsd:integer .

bv:Hut1 bv:capacity 6 .

