PREFIX uiaa-s: <https://www.theuiaa.org/4000-alps/schema/>

SELECT ?name ?range ?higherName ?higherRange
WHERE {
  ?summit uiaa-s:isolatedTo ?higher ;
          uiaa-s:peakName ?name ;
          uiaa-s:inRange ?range .
  ?higher uiaa-s:peakName ?higherName ;
          uiaa-s:inRange ?higherRange .
  FILTER (?range != ?higherRange)
}
ORDER BY ?name

