PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?name ?prominence (SUM(IF(CONTAINS(STR(?country), " and "), 2, 1)) AS ?countryCount)
WHERE {
  ?summit uiaa-s:peakName ?name ;
          uiaa-s:prominence ?promStr ;
          uiaa-s:country ?country .
  BIND (xsd:integer(STR(?promStr)) AS ?prominence)
  FILTER (?prominence > 300)
}
GROUP BY ?summit ?name ?prominence
HAVING (SUM(IF(CONTAINS(STR(?country), " and "), 2, 1)) > 1)
ORDER BY DESC(?prominence)

