@prefix uiaa-s: <https://www.theuiaa.org/4000-alps/schema/> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .

########### SCHEMA #####################################
## Conceptual scheme for 4000 meters peaks
<https://www.theuiaa.org/4000-alps/schema/four-thousanders> a skos:ConceptScheme .


########### CLASSES ####################################
## Summit
uiaa-s:summit a skos:Concept, rdfs:Class ;
    skos:inScheme uiaa-s:four-thousanders ;
    skos:definition "A summit is a point on a surface that is higher in elevation than all points immediately adjacent to it. Rules of UIAA recognize peaks with prominence higher than 30 meters or some significance in history of climbing.";
    skos:prefLabel "Summit" ;
    skos:altLabel "Peak" .

## Range
uiaa-s:range a skos:Concept, rdfs:Class ;
    skos:inScheme uiaa-s:four-thousanders ;
    skos:definition "A range. In this context apparently part of alps.";
    skos:example "Wallis Alps";
    skos:prefLabel "Range" .

########### PROPERTIES #################################
## Isolated to
uiaa-s:isolatedTo a skos:Concept, rdf:Property ;
    skos:prefLabel "isolated to" ;
    skos:definition "This property refers to the nearest higher summit to this one." ;
    skos:inScheme uiaa-s:four-thousanders;
    rdfs:domain uiaa-s:summit ;
    rdfs:range uiaa-s:summit .

## In range
uiaa-s:inRange a skos:Concept, rdf:Property ;
	skos:inScheme uiaa-s:four-thousanders ;
	skos:definition "This property refers to the range in which the summit is situated" ;
	skos:prefLabel "is in range" ;
	rdfs:domain uiaa-s:summit ;
	rdfs:range uiaa-s:range .

## Elevation
uiaa-s:elevation a skos:Concept, rdf:Property ;
	skos:inScheme uiaa-s:four-thousanders ;
	skos:definition "Elevation of the summit is a height difference in meters between the summit and the sea level." ;
	skos:prefLabel "has elevation" ;
	rdfs:domain uiaa-s:summit ;
	rdfs:range xsd:integer .

uiaa-s:firstAscentYear a skos:Concept, rdf:Property ;
	skos:inScheme uiaa-s:four-thousanders ;
	skos:definition "A date or just a year of the first successful ascent on the mounatin." ;
	skos:prefLabel "date of the first ascent" ;
	rdfs:domain uiaa-s:summit ;
	rdfs:range xsd:date .

uiaa-s:country a skos:Concept, rdf:Property ;
	skos:inScheme uiaa-s:four-thousanders ;
	skos:definition "Name of the country in which summit lies." ;
	skos:comment "For border summits, this property has more values." ;
	skos:prefLabel "country" ;
	rdfs:domain uiaa-s:summit ;
	rdfs:range xsd:string .

uiaa-s:prominence a skos:Concept, rdf:Property ;
	skos:inScheme uiaa-s:four-thousanders ;
	skos:definition "The prominence of a peak is the least drop in height in meters necessary in order to get from the summit to any higher terrain." ;
	skos:comment "An alternative equivalent definition is that the prominence is the height of the peak's summit above the lowest contour line encircling it, but containing no higher summit within it." ;
	skos:comment "Units of measure for prominence is meter." ;
	skos:prefLabel "prominence" ;
	rdfs:domain uiaa-s:summit ;
	rdfs:range xsd:float .

uiaa-s:isolation  a skos:Concept, rdf:Property ;
	skos:inScheme uiaa-s:four-thousanders ;
	skos:definition "The topographic isolation of a summit is the minimum distance to a point of equal elevation, representing a radius of dominance in which the peak is the highest point." ;
	skos:comment "The highest summit on Earth - Mount Everest - has indefinite isolation." ;
	skos:comment "Isolation is recorded in kilometers." ;
	skos:prefLabel "isolation" ;
	rdfs:domain uiaa-s:summit ;
	rdfs:range xsd:float .

uiaa-s:firstClimber a skos:Concept, rdf:Property ;
	skos:inScheme uiaa-s:four-thousanders ;
	skos:definition "The first person that has climbed to the summit." ;
	skos:comment "Usually there was a group of more climbers." ;
	skos:comment "Sometimes the names are unknown." ;
	skos:prefLabel "first climber on summit" ;
	rdfs:domain uiaa-s:summit ;
	rdfs:range xsd:string .

uiaa-s:highestSaddleToReachHigherSummit a skos:Concept, rdf:Property ;
	skos:inScheme uiaa-s:four-thousanders ;
	skos:definition "A col in geomorphology is the lowest point on a mountain ridge between two peaks." ;
	skos:comment "This is relevant to prominence. It is the highest place on the edge of circle with radius equal to prominence and center on the summit." ;
	skos:comment "Due to the origin data, this is just a string. It would be much more useful if this was an object." ;
	skos:prefLabel "highest saddle" ;
	skos:altLabel "col", "gap", "pass" ;
	rdfs:domain uiaa-s:summit ;
	rdfs:range xsd:string .

uiaa-s:peakName  a skos:Concept, rdf:Property ;
	skos:inScheme uiaa-s:four-thousanders ;
	skos:definition "Name of the summit in local language." ;
	skos:comment "Name often contains specification of the specific summit on the range, e.g. western summit, etc..." ;
	skos:prefLabel "summit name" ;
	rdfs:subPropertyOf skos:prefLabel ;
	rdfs:domain uiaa-s:summit .

